ratings = {'Python and pandas': 4, 'Statistics': 3, 'SQL': 4, 'DAX and Power BI': 2, 'Git and testing': 3, 'Interview practice': 2}
gaps = {k: 5 - v for k, v in ratings.items()}
total = sum(gaps.values())
planned = [(k, 24 * g / total) for k, g in sorted(gaps.items(), key=lambda kv: (-kv[1], kv[0])) if g >= 2]
for k, h in planned:
    print(f'{k}: {h:.1f} h')
print('areas planned:', len(planned))
print('hours planned:', round(sum(round(h, 1) for _, h in planned), 1))
